CREATE TABLE IF NOT EXISTS shares(id TEXT PRIMARY KEY,owner TEXT NOT NULL,name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,password TEXT,expires_at INTEGER NOT NULL,max_downloads INTEGER NOT NULL,downloads INTEGER NOT NULL DEFAULT 0,revoked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,code TEXT);
CREATE TABLE IF NOT EXISTS share_files(id TEXT PRIMARY KEY,share_id TEXT NOT NULL REFERENCES shares(id) ON DELETE CASCADE,name TEXT NOT NULL,size INTEGER NOT NULL,hash TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS shares_code ON shares(code);
CREATE TABLE IF NOT EXISTS share_codes(code TEXT PRIMARY KEY,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS share_uploads(id TEXT PRIMARY KEY,owner TEXT NOT NULL,session_hash TEXT NOT NULL,manifest TEXT NOT NULL,options TEXT NOT NULL,size INTEGER NOT NULL,expires_at INTEGER NOT NULL,result TEXT);
CREATE TABLE IF NOT EXISTS share_requests(id TEXT PRIMARY KEY,owner TEXT NOT NULL,name TEXT NOT NULL,code TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
